import { chromium } from 'playwright';
import { pathToFileURL } from 'node:url';
import { resolve } from 'node:path';
import { writeFileSync } from 'node:fs';
const browser = await chromium.launch(); const page = await browser.newPage();
await page.goto(pathToFileURL(resolve('dist/index.html')).href); await page.getByText('Reproduce a game').click(); await page.getByLabel('Board code').fill('np1-4-1'); await page.getByRole('button',{name:'Load board'}).click();
const cards = page.locator('.card'); let evidence = '# Automated accessibility-tree evidence\n\nChromium 156.0.8078.4, Playwright 1.64.1. These snapshots were captured from the offline HTML. No screen reader was used; spoken output remains for user acceptance. The board code was `np1-4-1`.\n\n';
async function capture(title) { evidence += `## ${title}\n\n\`\`\`yaml\n${await page.locator('body').ariaSnapshot()}\`\`\`\n\n`; }
await capture('Starting board and named controls'); await cards.first().focus(); await page.keyboard.press('Enter'); await capture('First revealed card');
await cards.nth(11).focus(); await page.keyboard.press('Enter'); await page.waitForTimeout(400); await capture('First matching pair');
const deck = [6,7,0,5,2,2,0,5,3,7,1,6,4,4,1,3];
for (const face of [0,1,2,3,4,5,7]) for (let i=0;i<deck.length;i++) if (deck[i]===face) { await cards.nth(i).focus(); await page.keyboard.press('Enter'); }
await page.waitForTimeout(2500); await capture('Final match and completion'); await page.keyboard.press('Tab'); evidence += `After Tab, focus was on: ${await page.evaluate(() => document.activeElement?.textContent)}. New Game remained available by name.\n`;
writeFileSync('docs/accessibility-evidence.md', evidence); await browser.close();
EOF
node evidence.mjs
rm evidence.mjs
